 * events: Array of { title, description, date (ISO string) }
 * filename: string (.ics)
 */
// PUBLIC_INTERFACE
export function exportToICS(events, filename = "examtrackr_events.ics") {
  function pad(n) {
    return n < 10 ? "0" + n : String(n);
  }
  let icsContent = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//ExamTrackr//EN"];
  for (const ev of events) {
    const dt = new Date(ev.date);
    const dtStr = dt.getUTCFullYear() + pad(dt.getUTCMonth() + 1) + pad(dt.getUTCDate()) + "T" + pad(dt.getUTCHours()) + pad(dt.getUTCMinutes()) + pad(dt.getUTCSeconds()) + "Z";
    icsContent.push("BEGIN:VEVENT", `SUMMARY:${ev.title}`, `DESCRIPTION:${ev.description || ""}`, `DTSTART:${dtStr}`, `DTEND:${dtStr}`, "END:VEVENT");
  }
  icsContent.push("END:VCALENDAR");
  const blob = new Blob([icsContent.join("\n")], {
    type: "text/calendar"
  });
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  setTimeout(() => {
    window.URL.revokeObjectURL(url);
    a.remove();
  }, 100);
}

